void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to [-0.5, 0.5], maintaining aspect ratio
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    // Rectangle parameters
    vec2 rectSize = vec2(0.3, 0.8);  // Width and height of the rectangle
    float radius = 0.03;              // Radius for the bottom-left corner

    // Rectangle bounds
    vec2 rectMin = -rectSize * 0.5;  // Bottom-left corner

    // Distance field computation
    vec2 p = uv;  // The point in the normalized space
    vec2 d = abs(p) - rectSize * 0.5;

    // Bottom-left rounded corner check
    float dist;
    if (p.x < rectMin.x + radius && p.y < rectMin.y + radius) {
        // Bottom-left corner: Circular rounding
        vec2 cornerCenter = vec2(rectMin.x + radius, rectMin.y + radius);
        dist = length(p - cornerCenter) - radius;
    } else {
        // Rectangle edges
        dist = max(d.x, d.y);
    }

    // Color the rectangle (green inside, white outside)
    vec4 color = dist < 0.0 ? vec4(0.0, 0.8, 0.3, 1.0) : vec4(0.0, 0.0, 0.0, 0.0);
    fragColor = color;
}
